/** The resource dimensions every plan caps. Adding a field here ripples into
 *  `PLAN_LIMITS`, `BillingService`, the usage UI and the limit guards. */
export type LimitedResource =
  | "seats"
  | "projects"
  | "issuesPerProject"
  | "storageMb"
  | "apiRequestsPerHour"
  | "webhooks";

/** Result of a single quota check, returned by `BillingService.checkLimit`. */
export interface LimitCheck {
  readonly resource: LimitedResource;
  readonly plan: PlanId;
  readonly limit: number;
  readonly used: number;
  readonly remaining: number;
  readonly exceeded: boolean;
}
import { describe, expect, it } from "vitest";
import {
  PLAN_LIMITS,
  PLAN_ORDER,
  UNLIMITED,
  getLimit,
  getPlanLimits,
  planAtLeast,
  wouldExceedLimit,
} from "@/config/plan-limits";
import { PLAN_IDS } from "@/types/billing";
import type { LimitedResource, PlanId } from "@/types/billing";

const NUMERIC_RESOURCES: LimitedResource[] = [
  "seats",
  "projects",
  "issuesPerProject",
  "storageMb",
  "apiRequestsPerHour",
  "webhooks",
];

describe("plan limits", () => {
  it("declares limits for every plan id, with no gaps", () => {
    for (const plan of PLAN_IDS) {
      expect(getPlanLimits(plan).plan).toBe(plan);
    }
    expect(PLAN_ORDER).toEqual([...PLAN_IDS]);
  });

